  function importData(file) {
    var reader=new FileReader();
    reader.onload=function(){
      try {
        var text=String(reader.result).replace(/^\uFEFF/,''),pkg;
        if(/\.csv$/i.test(file.name))pkg={players:parseCSV(text),metadata:{source:'User CSV import (unverified)',ratingSource:''}};
        else pkg=JSON.parse(text);
        var replace=pkg.format==='nhl-franchise-starting-data-v1';
        if(replace&&!window.confirm('Replace the starting database for NEW careers? Existing saved and active franchises will not change. Export your current starting data first to keep a copy.'))return;
        var count=stageDatabasePackage(pkg,replace);
        if(!$('starting-data-modal').hidden)startingDataModal(true);
        updateTeamHeadings(current.selected);
        setNotice(count+' player records added to the starting database for NEW careers. Your current franchise was not changed.'+(databasePersistent?'':' Session only - export starting data before closing.'),!databasePersistent);
      }catch(error){setNotice('Starting-data import failed: '+error.message,true);}
    };
    reader.onerror=function(){setNotice('The file could not be read. No starting data was changed.',true);};
    reader.readAsText(file);
  }
  function parseCSV(text) {
    // Quoted commas, escaped quotes and multiline fields are supported.
    var records=[],row=[],field='',quoted=false;
    text=String(text).replace(/^\uFEFF/,'');
    for(var i=0;i<text.length;i++){
      var ch=text[i];
      if(ch==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}
      else if(ch===','&&!quoted){row.push(field);field='';}
      else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(function(v){return v.trim()!=='';}))records.push(row);row=[];field='';}
      else field+=ch;
    }
    if(quoted)throw new Error('CSV contains an unclosed quoted field.');
    row.push(field);if(row.some(function(v){return v.trim()!=='';}))records.push(row);
    if(records.length<2)return [];
    var headers=records.shift().map(function(v){return v.trim();});
    return records.map(function(values,index){if(values.length!==headers.length)throw new Error('CSV row '+(index+2)+' has the wrong number of columns.');var obj={};headers.forEach(function(h,j){obj[h]=values[j].trim();});return obj;});
  }
