  function syncTeamData(code,prospectsOnly){
    return fetch('/api/team/'+encodeURIComponent(code)+'/sync'+(prospectsOnly?'?scope=prospects':''),{method:'POST',headers:{'Accept':'application/json'}}).then(function(r){return r.json().then(function(body){if(!r.ok)throw new Error(body.error||('HTTP '+r.status));return body;});}).then(function(pkg){return {team:code,count:storeSyncedPackage(pkg),metadata:pkg.metadata||{}};});
  }
