  function setSyncBusy(value){syncBusy=value;['sync-selected-team','sync-all-teams','sync-all-prospects'].forEach(function(id){var b=$(id);if(b)b.disabled=value;});}
  function runTeamSync(code){
    if(syncBusy)return Promise.resolve();setSyncBusy(true);setSyncProgress(0,1,'Requesting '+code);syncResult('Requesting authorized organization data...');
    return syncTeamData(code,false).then(function(info){setSyncProgress(1,1,'Request/import finished');syncResult(code+': '+info.count+' records merged into NEW-career starting data.\n'+(info.metadata.warnings||[]).join('\n'));return info;}).catch(function(err){setSyncProgress(0,1,'Team failed');syncResult(code+': '+err.message,true);}).finally(function(){setSyncBusy(false);});
  }
