        if(legacy){var old=normalizedDatabasePackage(JSON.parse(legacy),'BOS');importedRows=mergeImportedRows(importedRows,old.players);importedPicks=mergeImportedPicks(importedPicks,old.picks);importedTransactions=old.transactions;importedMetadata=Object.assign({},base.metadata,{name:'Offline starter + previous imports',revision:1});}
