    var marketRows=marketTargets.map(function(x){var p=x.p,selected=m.draft.marketPlayers.indexOf(p.id)>=0;return '<button class="target-row '+(selected?'selected':'')+'" data-trade-player="'+esc(p.id)+'" data-trade-side="market" aria-label="'+(selected?'Remove ':'Add ')+esc(p.name)+' to incoming package">'+officeAvatar(p)+'<span><strong>'+esc(p.name)+'</strong><small>'+esc(displayPlayerPosition(p))+' | '+p.ovr+' OVR | '+officeMoney(contractHit(p))+' · '+esc(x.fit.note)+(x.bundle?' · PACKAGE WITH '+esc(x.bundle.name.toUpperCase()):'')+'</small></span><b>'+officeIcon(selected?'check':'plus')+'</b></button>';}).join('')+(marketPick?'<button class="target-row pick-target" data-trade-pick="'+esc(pickKey(marketPick))+'" data-trade-side="market"><span class="target-pick-icon">'+officeIcon('box')+'</span><span><strong>'+marketPick.year+' Round '+marketPick.round+' Pick</strong><small>Future asset · simulated inventory</small></span></button>':'')||'<p class="panel-subtitle">No strong trade candidates are available right now.</p>';
    return '<section class="fo-panel partner-panel"><header>'+officeMark(id,'partner-crest')+'<div><h2>Trade partner: '+esc(team(id).name)+'</h2><p>Record: '+recordText(rec)+' <i></i> Cap space: <strong>'+officeMoney(g.cap-m.capB)+'</strong></p></div><button class="change-team" data-ui-modal="partner">'+officeIcon('trade')+'<span>Change team</span></button></header><div class="partner-scouting partner-scouting-symmetric"><div class="partner-needs"><h3>Their needs</h3>'+officeNeedsMarkup(g,id,false)+'</div><div class="partner-targets"><h3>'+g.team+' targets <span>('+id+')</span></h3>'+userRows+'</div><div class="partner-targets partner-return-targets"><h3>'+id+' targets <span>('+g.team+')</span></h3>'+marketRows+'</div></div><footer>'+planTitle(m.other.plan)+'<span>SIMULATED GM PRIORITIES</span></footer></section>';
