  function officeFuturePage(g){
    var picks=clubPicks(g,g.team).slice().sort(function(a,b){return a.year-b.year||a.round-b.round;}),res=(g.reserveRoster||[]).concat(g.orgProspects||[]),years=Array.from(new Set(picks.map(function(p){return p.year;})));
    return officeHeader(team(g.team).name,'Future assets','Draft capital and the players currently held outside your active roster.','<button class="button" data-ui-page="development">Development pipeline</button>')+'<div class="future-grid">'+years.map(function(y){return '<section class="fo-panel detail-panel"><div class="panel-head"><h2>'+y+' NHL Draft</h2><span class="small-badge">'+picks.filter(function(p){return p.year===y;}).length+' PICKS</span></div>'+picks.filter(function(p){return p.year===y;}).map(function(p){return '<div class="future-pick">'+officeIcon('box')+'<strong>Round '+p.round+'</strong><span>'+esc(p.origin||p.team)+'</span><small>'+esc(p.condition||'No condition recorded')+'</small></div>';}).join('')+'</section>';}).join('')+'</div><section class="fo-panel detail-panel"><div class="panel-head"><h2>Reserves &amp; organizational players</h2><span class="small-badge">'+res.length+' LOADED</span></div><p class="panel-subtitle">These are loaded records, not a complete prospect pool. Injured/non-roster veterans may also be included. Generated future draft classes are separate.</p>'+officeSimplePlayerTable(res)+'</section>';
  }
  function officeSimplePlayerTable(list){return '<div class="player-table-wrap"><table class="player-table"><thead><tr><th>Player</th><th>Pos</th><th>Age</th><th>Sim OVR</th><th>Status</th><th>Club / league</th></tr></thead><tbody>'+(list.length?list.map(function(p){return '<tr><td class="player-name">'+esc(p.name)+'</td><td>'+esc(displayPlayerPosition(p))+'</td><td>'+p.age+'</td><td>'+p.ovr+'</td><td>'+esc(p.rosterStatus||'Development')+'</td><td>'+esc(p.currentTeam||p.level||'Not supplied')+(p.currentLeague?' / '+esc(p.currentLeague):'')+'</td></tr>';}).join(''):'<tr><td colspan="6">No organization players have been loaded here.</td></tr>')+'</tbody></table></div>';}
  function officeUpcomingPage(g){
    var rows=[];teams.forEach(function(t){clubRoster(g,t.id).forEach(function(p){if(Number(p.years)<=1)rows.push({p:p,id:t.id});});});rows.sort(function(a,b){return b.p.ovr-a.p.ovr;});
    return officeHeader('League personnel','Upcoming free agents','Players with one season or less remaining in this career. Not a verified real-world free-agent list.')+'<section class="fo-panel detail-panel"><div class="player-table-wrap"><table class="player-table"><thead><tr><th>Player</th><th>Club</th><th>Pos</th><th>Age</th><th>Sim OVR</th><th>Cap hit</th><th>Expiry</th></tr></thead><tbody>'+rows.map(function(r){var p=r.p;return '<tr><td class="player-name">'+esc(p.name)+'</td><td>'+esc(r.id)+'</td><td>'+esc(displayPlayerPosition(p))+'</td><td>'+p.age+'</td><td>'+p.ovr+'</td><td>'+officeMoney(contractHit(p))+'</td><td>'+esc(p.freeAgencyStatus||'Not supplied')+'</td></tr>';}).join('')+'</tbody></table></div></section>';
  }
