  renderPage=function(){
    var g=current.game;if(!g)return;
    if(current.page==='overview'&&g.mode!=='playoffs')renderHomeDashboard(g);
    else if(current.page==='frontoffice')$('office-content').innerHTML=officeFrontPage(g);
    else if(current.page==='futureassets')$('office-content').innerHTML=officeFuturePage(g);
    else if(current.page==='upcoming')$('office-content').innerHTML=officeUpcomingPage(g);
    else if(current.page==='clauses')$('office-content').innerHTML=officeClausePage(g);
    else if(current.page==='salarycap')$('office-content').innerHTML=officeCapPage(g);
    else if(current.page==='roster')renderRosterOverview(g);
    else if(current.page==='intentions')$('office-content').innerHTML=officeIntentionsPage(g,false);
    else if(current.page==='partnerrecord')$('office-content').innerHTML=officeResignPage(g);
    else if(current.page==='schedule')$('office-content').innerHTML=officeSchedulePage(g);
    else if(current.page==='analytics')$('office-content').innerHTML=officeAnalyticsPage(g);
    else if(current.page==='offseason')renderOffseasonHub(g);
    else if(current.page==='lines')renderDepthChart(g);
    else if(current.page==='development'){current.orgTeam=g.team;current.orgTab='prospects';renderOrganization(g);}
    else if(current.page==='coachneeds')$('office-content').innerHTML=officeMeetingsPage(g);
    else originalRenderPage();
    updateOfficeShell();
  };
  bindEvents=function(){originalBindEvents();officeBindEvents();};
