  // Calibrated shared market scale: player tiers and roster roles are modest inputs, never multipliers.
  tradePremium=function(p){var tier=playerPotentialRole(p),bonus=tier==='Franchise'?28:(tier==='Top Line'||tier==='Top 2')?20:(tier==='Top 6'||tier==='Top 4')?12:0;return 1+bonus/100;};
  pickValue=function(g,p){var round=Math.max(1,Number(p.round)||1),slot=p.overall?((Number(p.overall)-1)%32)+1:draftSlotForTeam(g,p.origin||p.team),base=round===1?205:round===2?88:round===3?43:round===4?22:round===5?13:round===6?8:5,slotFactor=round===1?1.18-.0058*(slot-1):1.1-.0032*(slot-1),yearNow=(g.offseason&&g.offseason.year)||g.startYear+g.season,yearsAhead=Math.max(0,(Number(p.year)||yearNow)-yearNow);return Math.max(2,Math.round(base*slotFactor*Math.pow(.82,yearsAhead)));};
  basePlayerValue=function(p){var ovr=Math.max(45,Number(p.ovr)||55),age=Math.max(18,Number(p.age)||27),potential=Math.max(ovr,Number(p.potential)||ovr),years=Math.max(0,Number(p.years)||0),salary=contractHit(p),skill=Math.pow(Math.max(0,ovr-48),1.48)*1.03,upside=Math.min(85,Math.max(0,potential-ovr)*3.1),prime=age<24?(24-age)*5:age>29?-(age-29)*7:0,control=Math.min(22,years*5),production=Math.min(28,Math.max(-12,(Number(p.points)||0)*.22-(ovr-55)*.9)),capPenalty=Math.max(-35,Math.min(24,((ovr*95000-salary)/1000000)*5));return Math.max(4,Math.round((skill+upside+prime+control+production+capPenalty)*(p.pos==='G'?.92:1)));};
  gmAssetValue=function(g,id,asset){if(!asset)return 0;if(asset.round){var raw=pickValue(g,asset),plan=officePlan(g,id);return Math.round(raw*(plan==='rebuild'?1.08:plan==='contend'?.96:1));}var market=basePlayerValue(asset),plan=officePlan(g,id),v=market,needs=officeNeeds(g,id),label=asset.pos==='C'?'Center depth':asset.pos==='D'?(shotHand(asset)==='R'&&rightDefenseNeed(g,id)?'Right-shot defense':'Defense depth'):asset.pos==='G'?'Goaltending':'Top 6 scoring',need=needs.find(function(n){return n.label===label;});if(plan==='rebuild'&&asset.age<=25)v+=Math.min(24,(25-asset.age)*2);if(plan==='contend'&&asset.ovr>=82)v+=Math.min(18,(asset.ovr-81)*1.2);if(need&&need.level==='High')v+=Math.min(15,Math.round(market*.09));else if(need&&need.level==='Medium')v+=Math.min(7,Math.round(market*.04));if(isOnTradeBlock(g,id,asset))v*=.9;else v*=tradePremium(asset);if(asset.pos==='D'&&shotHand(asset)==='R'&&rightDefenseNeed(g,id))v+=Math.min(10,Math.round(market*.05));var projection=nhlPointProjection(g,asset);if(projection&&asset.pos!=='G'){var expected=Math.max(12,(Number(asset.ovr||65)-55)*.85),factor=clamp(.98+(projection.points-expected)/Math.max(60,expected*5),.9,1.1);v*=factor;}var role=premiumRosterRole(g,premiumAssetOwner(g,id,asset),asset);if(role)v+=Math.min(12,Math.round(market*.06));var leverage=Math.min(100,playerLeverageScore(g,id,asset));if(leverage>35)v*=1-Math.min(.18,(leverage-35)*.0028);return Math.max(2,Math.round(v));};
  function valueGrade(delta,base){var pct=delta/Math.max(1,base);return pct>=.3?'A':pct>=.18?'B+':pct>=.08?'B':pct>=-.07?'C':pct>=-.18?'D':'F';}
  try{init();}catch(e){var box=$('fatal-message');box.hidden=false;$('fatal-detail').textContent='Startup error: '+e.message;}
